from dataclasses import dataclass
from typing import TypedDict

class LessonRow(TypedDict):
    title: str
    minutes: int

@dataclass
class Lesson:
    title: str
    minutes: int

def validated_lesson(raw: object) -> Lesson:
    if not isinstance(raw, dict):
        raise ValueError('row must be an object')
    title = raw.get('title')
    minutes = raw.get('minutes')
    if not isinstance(title, str) or not title.strip() or type(minutes) is not int or minutes < 0:
        raise ValueError('invalid lesson fields')
    return Lesson(title.strip(), minutes)

print(validated_lesson({'title': ' Input ', 'minutes': 8}))
try:
    validated_lesson({'title': 'Input', 'minutes': True})
except ValueError:
    print('invalid row rejected')
